.linux:lang(ko) { font-family: system-ui, "Ubuntu", "Droid Sans", "Source Han Sans K", "Source Han Sans JR", "Source Han Sans", "UnDotum", "FBaekmuk Gulim", sans-serif; }

body {
	margin: 0;
	padding: 0;
	height: 100%;
	width: 100%;
	user-select: none;
	color: #cccccc;
}

.cpu {
	width: 60px;
}

.pid {
	width: 50px
}

.memory {
	width: 90px;
}

.monaco-list:focus {
	outline: 0;
}

.monaco-list-row:first-of-type {
	border-bottom: 1px solid;
}

.row {
	display: flex;
}

.centered {
	text-align: center;
}

.nameLabel{
	text-align: left;
	width: calc(100% - 185px);
	overflow: hidden;
	text-overflow: ellipsis;
}

.data {
	white-space: pre;
	padding-left: .5rem;
	font-weight: normal;
	text-align: left;
	height: 22px;
}

.error {
	padding-left: 20px;
	white-space: nowrap;
}
